const t = $input.first().json;
const decode = (b64) => Buffer.from(b64.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
const walk = (part) => {
  if (!part) return { text: '', html: '' };
  if (part.mimeType === 'text/plain' && part.body && part.body.data) return { text: decode(part.body.data), html: '' };
  if (part.mimeType === 'text/html' && part.body && part.body.data) return { text: '', html: decode(part.body.data) };
  return (part.parts || []).map(walk).reduce((a, b) => ({ text: a.text + b.text, html: a.html + b.html }), { text: '', html: '' });
};
const stripHtml = (h) => h.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/[ \t]+/g, ' ');
const tidy = (s) => s.split('\n').filter(l => !l.trim().startsWith('>')).join('\n')
  .split(/\nOn .{10,120} wrote:/)[0].replace(/\n{3,}/g, '\n\n').trim().slice(0, 1500);
// Header lookup: Gmail payload header list, falling back to the flat header keys n8n adds
const hdr = (m, name) => ((m.payload && m.payload.headers) || []).find(h => h.name.toLowerCase() === name)?.value
  || m[name.charAt(0).toUpperCase() + name.slice(1)] || '';
const messages = (t.messages || []).slice(-6).map(m => {
  const { text, html } = walk(m.payload);
  return { from: hdr(m, 'from'), date: new Date(Number(m.internalDate)).toISOString(), body: tidy(text || stripHtml(html)) };
});
return [{ json: { thread_id: t.id, untrusted_email_content: true, messages } }];
